public class InnerMessageTemplateMessageTemplateAttributesFactory(Action<Humidifier.Wisdom.MessageTemplateTypes.MessageTemplateAttributes> factoryAction = null) : SubResourceFactory<Humidifier.Wisdom.MessageTemplateTypes.MessageTemplateAttributes>
{

    internal InnerMessageTemplateSystemAttributesFactory SystemAttributesFactory { get; set; }

    internal InnerMessageTemplateAgentAttributesFactory AgentAttributesFactory { get; set; }

    internal InnerMessageTemplateCustomerProfileAttributesFactory CustomerProfileAttributesFactory { get; set; }

    protected override Humidifier.Wisdom.MessageTemplateTypes.MessageTemplateAttributes Create()
    {
        var messageTemplateAttributesResult = CreateMessageTemplateAttributes();
        factoryAction?.Invoke(messageTemplateAttributesResult);

        return messageTemplateAttributesResult;
    }

    private Humidifier.Wisdom.MessageTemplateTypes.MessageTemplateAttributes CreateMessageTemplateAttributes()
    {
        var messageTemplateAttributesResult = new Humidifier.Wisdom.MessageTemplateTypes.MessageTemplateAttributes();

        return messageTemplateAttributesResult;
    }
    public override void CreateChildren(Humidifier.Wisdom.MessageTemplateTypes.MessageTemplateAttributes result)
    {
        base.CreateChildren(result);

        result.SystemAttributes ??= SystemAttributesFactory?.Build();
        result.AgentAttributes ??= AgentAttributesFactory?.Build();
        result.CustomerProfileAttributes ??= CustomerProfileAttributesFactory?.Build();
    }

} // End Of Class

